"use client";

import { ConnectionSurface, connectionTarget } from "@diax/react/connect";
import type { DiaxRelation } from "diax";
import {
  BellRing,
  ChartNoAxesCombined,
  Database,
  FileCode2,
  type LucideIcon,
  Play,
  Settings2,
  ShieldCheck,
  UploadCloud,
} from "lucide-react";
import type { ReactNode } from "react";

const stages = [
  {
    id: "relay-configure",
    index: "01",
    eyebrow: "Intent",
    title: "Configure policy",
    technology: "Typed form schema",
    description: "Teams choose the checks they need without hand-authoring pipeline YAML.",
    items: ["Visible dependencies", "Guarded defaults"],
    outcome: "Validated input",
    icon: Settings2,
    tone: "blue",
  },
  {
    id: "relay-generate",
    index: "02",
    eyebrow: "Materialize",
    title: "Generate workflow",
    technology: "Conditional template",
    description: "A versioned template turns policy into one reviewable execution plan.",
    items: ["Only enabled checks render", "Hooks stay ordered", "Output remains reproducible"],
    outcome: "Pipeline manifest",
    icon: FileCode2,
    tone: "blue",
  },
  {
    id: "relay-execute",
    index: "03",
    eyebrow: "Execute",
    title: "Run independent checks",
    technology: "CI runner",
    description:
      "Every scanner finishes and records evidence before the release policy evaluates the run.",
    items: [
      "Static analysis",
      "Supply-chain review",
      "Contract and type checks",
      "Failure writes evidence instead of exiting early",
    ],
    outcome: "Complete evidence",
    icon: Play,
    tone: "orange",
  },
  {
    id: "relay-report",
    index: "04",
    eyebrow: "Transport",
    title: "Normalize reports",
    technology: "Webhook boundary",
    description: "Tool-specific output is translated into stable, source-linked records.",
    items: ["Schema validation", "Idempotent delivery"],
    outcome: "Normalized records",
    icon: UploadCloud,
    tone: "orange",
  },
  {
    id: "relay-aggregate",
    index: "05",
    eyebrow: "Aggregate",
    title: "Refresh the read model",
    technology: "Transactional upsert",
    description:
      "Independent reports converge into one project snapshot optimized for product reads.",
    items: ["Write-time aggregation", "Branch identity", "Repeat delivery stays clean"],
    outcome: "Quality snapshot",
    icon: Database,
    tone: "violet",
  },
  {
    id: "relay-explain",
    index: "06",
    eyebrow: "Explain",
    title: "Present progressive detail",
    technology: "Semantic DOM",
    description:
      "A current run, a project trend and an organization view reuse the same evidence contract.",
    items: ["Run diagnostics", "Thirty-run trend", "Portfolio distribution"],
    outcome: "Decision context",
    icon: ChartNoAxesCombined,
    tone: "teal",
  },
  {
    id: "relay-notify",
    index: "07",
    eyebrow: "Act",
    title: "Deliver accountable alerts",
    technology: "Subscription rules",
    description: "Teams receive the smallest message that still explains what changed and why.",
    items: ["Real-time incident", "Weekly digest"],
    outcome: "Owned follow-up",
    icon: BellRing,
    tone: "teal",
  },
] as const;

type Tone = (typeof stages)[number]["tone"];

const toneClasses: Record<Tone, { rail: string; text: string; wash: string }> = {
  blue: { rail: "bg-[#2d5f86]", text: "text-[#2d5f86]", wash: "bg-[#e7f0f7]" },
  orange: { rail: "bg-[#b86332]", text: "text-[#a54d1d]", wash: "bg-[#f7ece5]" },
  violet: { rail: "bg-[#65559a]", text: "text-[#65559a]", wash: "bg-[#eeebf7]" },
  teal: { rail: "bg-[#27766f]", text: "text-[#27766f]", wash: "bg-[#e4f1ef]" },
};

const relations = stages.slice(0, -1).map((stage, index) => ({
  id: `relay-${index + 1}-${index + 2}`,
  from: stage.id,
  to: stages[index + 1].id,
  color: "#46606f",
  targetMarker: "arrow" as const,
  gap: 8,
  label: <TransitLabel>{stages[index + 1].outcome}</TransitLabel>,
})) satisfies readonly DiaxRelation<ReactNode>[];

const guarantees = [
  ["Policy", "Unsafe checks cannot be disabled silently"],
  ["Execution", "One tool crash does not erase other evidence"],
  ["Delivery", "Retries remain idempotent"],
  ["Experience", "Refreshes preserve the last useful state"],
] as const;

export default function ResilientDataRelay() {
  return (
    <figure
      data-showcase-corpus="resilient-data-relay"
      className="w-full max-w-[1120px] overflow-hidden border border-[#9aaab4] bg-[#e7edf0] text-[#13212b] shadow-[0_24px_70px_rgb(31_47_60_/_0.2)] [border-radius:3px]"
    >
      <figcaption className="grid gap-4 border-b border-[#83949f] bg-[#14232d] p-4 text-white sm:grid-cols-[minmax(0,1fr)_auto] sm:items-end sm:p-6">
        <div>
          <p className="m-0 font-mono text-[9px] font-bold uppercase tracking-[0.14em] text-[#8bbec5]">
            Long-form measurement corpus · Authored DOM
          </p>
          <h2 className="m-0 mt-1 text-xl font-semibold tracking-[-0.04em] sm:text-3xl">
            Resilient data relay
          </h2>
          <p className="m-0 mt-1 max-w-2xl text-[10px] leading-relaxed text-slate-300 sm:text-xs">
            Seven unequal-height stages preserve a single reading order while DiaX keeps every
            measured transition attached to live content.
          </p>
        </div>
        <dl className="m-0 flex gap-4 font-mono text-[8px] text-slate-400">
          <Stat label="Stages" value="7" />
          <Stat label="Labels" value="6" />
          <Stat label="Anchors" value="0" />
        </dl>
      </figcaption>

      <div className="border-b border-[#9aaab4] bg-[#dbe4e8] px-4 py-3 sm:px-6">
        <ol className="m-0 flex list-none flex-wrap items-center gap-x-2 gap-y-1 p-0 font-mono text-[7px] font-bold uppercase tracking-[0.08em] text-[#4b606d] sm:text-[9px]">
          {stages.map((stage, index) => (
            <li key={stage.id} className="flex items-center gap-2">
              {index > 0 ? <span aria-hidden="true">→</span> : null}
              <span>{stage.eyebrow}</span>
            </li>
          ))}
        </ol>
      </div>

      <ConnectionSurface
        relations={relations}
        pathType="orthogonal"
        aria-label="Resilient data relay stages"
        className="grid gap-16 bg-[#eef2f4] p-3 pb-16 [background-image:linear-gradient(rgb(19_33_43_/_0.045)_1px,transparent_1px)] [background-size:100%_24px] sm:p-6 sm:pb-16"
      >
        {stages.map((stage) => (
          <RelayStage key={stage.id} {...stage} />
        ))}
      </ConnectionSurface>

      <section
        className="border-t border-[#9aaab4] bg-[#dbe4e8] p-3 sm:p-5"
        aria-labelledby="relay-guarantees"
      >
        <div className="flex items-center gap-2">
          <ShieldCheck aria-hidden="true" className="size-4 text-[#27766f]" />
          <h3
            id="relay-guarantees"
            className="m-0 font-mono text-[9px] font-bold uppercase tracking-[0.12em] text-[#324955]"
          >
            Failure boundaries
          </h3>
        </div>
        <dl className="m-0 mt-3 grid border-y border-[#a9b7bf] sm:grid-cols-4">
          {guarantees.map(([term, description]) => (
            <div key={term} className="border-[#a9b7bf] px-2 py-3 sm:border-l sm:first:border-l-0">
              <dt className="font-mono text-[7px] font-bold uppercase tracking-[0.1em] text-[#27766f]">
                {term}
              </dt>
              <dd className="m-0 mt-1 text-[7px] leading-relaxed text-[#526570] sm:text-[9px]">
                {description}
              </dd>
            </div>
          ))}
        </dl>
      </section>
    </figure>
  );
}

function RelayStage({
  id,
  index,
  eyebrow,
  title,
  technology,
  description,
  items,
  outcome,
  icon: Icon,
  tone,
}: {
  id: string;
  index: string;
  eyebrow: string;
  title: string;
  technology: string;
  description: string;
  items: readonly string[];
  outcome: string;
  icon: LucideIcon;
  tone: Tone;
}) {
  const colors = toneClasses[tone];
  return (
    <article
      {...connectionTarget(id)}
      className="relative mx-auto grid w-full max-w-[920px] grid-cols-[34px_minmax(0,1fr)] overflow-hidden border border-[#a7b4bc] bg-white shadow-[0_10px_24px_rgb(31_47_60_/_0.1)] [border-radius:2px] sm:grid-cols-[46px_minmax(0,1fr)_170px]"
    >
      <div className={`${colors.rail} flex items-start justify-center py-3 text-white sm:py-4`}>
        <span className="font-mono text-[8px] font-bold tracking-[0.08em] sm:text-[10px]">
          {index}
        </span>
      </div>
      <div className="min-w-0 p-3 sm:p-4">
        <div className="flex flex-wrap items-center gap-2">
          <Icon aria-hidden="true" className={`size-3.5 ${colors.text}`} />
          <span
            className={`font-mono text-[7px] font-bold uppercase tracking-[0.1em] ${colors.text}`}
          >
            {eyebrow}
          </span>
          <code className={`${colors.wash} ${colors.text} px-1.5 py-0.5 text-[6px] sm:text-[8px]`}>
            {technology}
          </code>
        </div>
        <h3 className="m-0 mt-1.5 text-[11px] font-semibold tracking-[-0.02em] sm:text-sm">
          {title}
        </h3>
        <p className="m-0 mt-1 max-w-2xl text-[7px] leading-relaxed text-[#5d6d76] sm:text-[9px]">
          {description}
        </p>
        <ul className="m-0 mt-2 grid list-none gap-1 p-0 sm:grid-cols-2">
          {items.map((item) => (
            <li
              key={item}
              className="border border-[#c6d0d5] bg-[#f6f8f9] px-1.5 py-1 text-[6px] text-[#41545f] sm:text-[8px]"
            >
              {item}
            </li>
          ))}
        </ul>
      </div>
      <div className="col-start-2 flex items-center border-t border-[#d0d8dc] px-3 py-2 sm:col-start-3 sm:row-start-1 sm:border-t-0 sm:border-l sm:px-4">
        <div>
          <p className="m-0 font-mono text-[6px] font-bold uppercase tracking-[0.1em] text-[#7b8a92] sm:text-[7px]">
            Handoff
          </p>
          <p className="m-0 mt-1 text-[8px] font-semibold text-[#243944] sm:text-[10px]">
            {outcome}
          </p>
        </div>
      </div>
    </article>
  );
}

function TransitLabel({ children }: { children: ReactNode }) {
  return (
    <span className="border border-[#95a5ae] bg-[#eef2f4] px-2 py-1 font-mono text-[6px] font-bold uppercase tracking-[0.08em] text-[#405660] sm:text-[8px]">
      {children}
    </span>
  );
}

function Stat({ label, value }: { label: string; value: string }) {
  return (
    <div>
      <dt>{label}</dt>
      <dd className="m-0 mt-0.5 text-base font-semibold text-white">{value}</dd>
    </div>
  );
}
